{"command":"python3 -c '
import pty, os, termios, fcntl

def run_xplr(args):
    master, slave = pty.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.setsid()
        fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.execv("./executable", ["./executable"] + args)
    else:
        os.close(slave)
        output = b""
        while True:
            try:
                data = os.read(master, 1024)
                if not data:
                    break
                output += data
            except OSError:
                break
        os.waitpid(pid, 0)
        return output.decode("utf-8", errors="replace")

print(repr(run_xplr(["/tmp", "/tmp/test_cargo", "--on-load", "PrintSelectionAndQuit"])))
'"}

