use crate::lua::lexer::{Lexer, Token};

#[derive(Debug, Clone)]
pub enum Expr {
    Nil,
    Bool(bool),
    Number(f64),
    String(String),
    Vararg,
    Var(String),
    Index {
        target: Box<Expr>,
        key: Box<Expr>,
    },
    Field {
        target: Box<Expr>,
        field: String,
    },
    Call {
        func: Box<Expr>,
        args: Vec<Expr>,
    },
    MethodCall {
        target: Box<Expr>,
        method: String,
        args: Vec<Expr>,
    },
    Table(Vec<(Option<Expr>, Expr)>),
    Function {
        params: Vec<String>,
        vararg: bool,
        body: Vec<Stmt>,
    },
    BinOp {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    UnaryOp {
        op: String,
        expr: Box<Expr>,
    },
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Assign {
        targets: Vec<Expr>,
        values: Vec<Expr>,
    },
    LocalAssign {
        names: Vec<String>,
        values: Vec<Expr>,
    },
    Call(Expr),
    If {
        cond_blocks: Vec<(Expr, Vec<Stmt>)>,
        else_block: Option<Vec<Stmt>>,
    },
    ForNum {
        name: String,
        start: Expr,
        stop: Expr,
        step: Option<Expr>,
        body: Vec<Stmt>,
    },
    ForIn {
        names: Vec<String>,
        exprs: Vec<Expr>,
        body: Vec<Stmt>,
    },
    While {
        cond: Expr,
        body: Vec<Stmt>,
    },
    Repeat {
        body: Vec<Stmt>,
        cond: Expr,
    },
    Return(Vec<Expr>),
    Break,
}

pub struct Parser<'a> {
    lexer: Lexer<'a>,
    current: Token,
}

impl<'a> Parser<'a> {
    pub fn new(input: &'a str) -> Result<Self, String> {
        let mut lexer = Lexer::new(input);
        let current = lexer.next_token()?;
        Ok(Parser { lexer, current })
    }

    fn advance(&mut self) -> Result<Token, String> {
        let prev = self.current.clone();
        self.current = self.lexer.next_token()?;
        Ok(prev)
    }

    fn check_keyword(&self, kw: &str) -> bool {
        matches!(&self.current, Token::Keyword(s) if s == kw)
    }

    fn check_symbol(&self, sym: &str) -> bool {
        matches!(&self.current, Token::Symbol(s) if s == sym)
    }

    fn consume_keyword(&mut self, kw: &str) -> Result<(), String> {
        if self.check_keyword(kw) {
            self.advance()?;
            Ok(())
        } else {
            Err(format!("Expected keyword '{}', got {:?}", kw, self.current))
        }
    }

    fn consume_symbol(&mut self, sym: &str) -> Result<(), String> {
        if self.check_symbol(sym) {
            self.advance()?;
            Ok(())
        } else {
            Err(format!("Expected symbol '{}', got {:?}", sym, self.current))
        }
    }

    fn parse_ident(&mut self) -> Result<String, String> {
        match self.advance()? {
            Token::Ident(s) => Ok(s),
            other => Err(format!("Expected identifier, got {:?}", other)),
        }
    }

    pub fn parse_chunk(&mut self) -> Result<Vec<Stmt>, String> {
        let mut stmts = Vec::new();
        while self.current != Token::Eof {
            if self.check_keyword("end")
                || self.check_keyword("else")
                || self.check_keyword("elseif")
                || self.check_keyword("until")
            {
                break;
            }
            if self.check_symbol(";") {
                self.advance()?;
                continue;
            }
            stmts.push(self.parse_stmt()?);
        }
        Ok(stmts)
    }

    fn parse_stmt(&mut self) -> Result<Stmt, String> {
        if self.check_keyword("local") {
            self.advance()?;
            if self.check_keyword("function") {
                self.advance()?;
                let name = self.parse_ident()?;
                let (params, vararg, body) = self.parse_func_body()?;
                return Ok(Stmt::LocalAssign {
                    names: vec![name],
                    values: vec![Expr::Function {
                        params,
                        vararg,
                        body,
                    }],
                });
            } else {
                let mut names = vec![self.parse_ident()?];
                while self.check_symbol(",") {
                    self.advance()?;
                    names.push(self.parse_ident()?);
                }
                let mut values = Vec::new();
                if self.check_symbol("=") {
                    self.advance()?;
                    values = self.parse_expr_list()?;
                }
                return Ok(Stmt::LocalAssign { names, values });
            }
        }

        if self.check_keyword("if") {
            self.advance()?;
            let mut cond_blocks = Vec::new();
            let cond = self.parse_expr()?;
            self.consume_keyword("then")?;
            let body = self.parse_chunk()?;
            cond_blocks.push((cond, body));

            while self.check_keyword("elseif") {
                self.advance()?;
                let c = self.parse_expr()?;
                self.consume_keyword("then")?;
                let b = self.parse_chunk()?;
                cond_blocks.push((c, b));
            }

            let mut else_block = None;
            if self.check_keyword("else") {
                self.advance()?;
                else_block = Some(self.parse_chunk()?);
            }
            self.consume_keyword("end")?;
            return Ok(Stmt::If {
                cond_blocks,
                else_block,
            });
        }

        if self.check_keyword("return") {
            self.advance()?;
            let mut exprs = Vec::new();
            if !self.check_keyword("end")
                && !self.check_keyword("else")
                && !self.check_keyword("elseif")
                && !self.check_keyword("until")
                && self.current != Token::Eof
                && !self.check_symbol(";")
            {
                exprs = self.parse_expr_list()?;
            }
            if self.check_symbol(";") {
                self.advance()?;
            }
            return Ok(Stmt::Return(exprs));
        }

        if self.check_keyword("break") {
            self.advance()?;
            return Ok(Stmt::Break);
        }

        if self.check_keyword("for") {
            self.advance()?;
            let name = self.parse_ident()?;
            if self.check_symbol("=") {
                self.advance()?;
                let start = self.parse_expr()?;
                self.consume_symbol(",")?;
                let stop = self.parse_expr()?;
                let mut step = None;
                if self.check_symbol(",") {
                    self.advance()?;
                    step = Some(self.parse_expr()?);
                }
                self.consume_keyword("do")?;
                let body = self.parse_chunk()?;
                self.consume_keyword("end")?;
                return Ok(Stmt::ForNum {
                    name,
                    start,
                    stop,
                    step,
                    body,
                });
            } else {
                let mut names = vec![name];
                while self.check_symbol(",") {
                    self.advance()?;
                    names.push(self.parse_ident()?);
                }
                self.consume_keyword("in")?;
                let exprs = self.parse_expr_list()?;
                self.consume_keyword("do")?;
                let body = self.parse_chunk()?;
                self.consume_keyword("end")?;
                return Ok(Stmt::ForIn { names, exprs, body });
            }
        }

        if self.check_keyword("while") {
            self.advance()?;
            let cond = self.parse_expr()?;
            self.consume_keyword("do")?;
            let body = self.parse_chunk()?;
            self.consume_keyword("end")?;
            return Ok(Stmt::While { cond, body });
        }

        if self.check_keyword("function") {
            self.advance()?;
            let mut target = Expr::Var(self.parse_ident()?);
            while self.check_symbol(".") {
                self.advance()?;
                let field = self.parse_ident()?;
                target = Expr::Field {
                    target: Box::new(target),
                    field,
                };
            }
            let (params, vararg, body) = self.parse_func_body()?;
            return Ok(Stmt::Assign {
                targets: vec![target],
                values: vec![Expr::Function {
                    params,
                    vararg,
                    body,
                }],
            });
        }

        // Expression statement or assignment
        let first_expr = self.parse_primary_expr()?;
        if self.check_symbol(",") || self.check_symbol("=") {
            let mut targets = vec![first_expr];
            while self.check_symbol(",") {
                self.advance()?;
                targets.push(self.parse_primary_expr()?);
            }
            self.consume_symbol("=")?;
            let values = self.parse_expr_list()?;
            Ok(Stmt::Assign { targets, values })
        } else {
            Ok(Stmt::Call(first_expr))
        }
    }

    fn parse_func_body(&mut self) -> Result<(Vec<String>, bool, Vec<Stmt>), String> {
        self.consume_symbol("(")?;
        let mut params = Vec::new();
        let mut vararg = false;
        if !self.check_symbol(")") {
            if self.check_symbol("...") {
                self.advance()?;
                vararg = true;
            } else {
                params.push(self.parse_ident()?);
                while self.check_symbol(",") {
                    self.advance()?;
                    if self.check_symbol("...") {
                        self.advance()?;
                        vararg = true;
                        break;
                    } else {
                        params.push(self.parse_ident()?);
                    }
                }
            }
        }
        self.consume_symbol(")")?;
        let body = self.parse_chunk()?;
        self.consume_keyword("end")?;
        Ok((params, vararg, body))
    }

    fn parse_expr_list(&mut self) -> Result<Vec<Expr>, String> {
        let mut exprs = vec![self.parse_expr()?];
        while self.check_symbol(",") {
            self.advance()?;
            exprs.push(self.parse_expr()?);
        }
        Ok(exprs)
    }

    pub fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_sub_expr(0)
    }

    fn parse_sub_expr(&mut self, limit: u8) -> Result<Expr, String> {
        let mut left = if self.check_keyword("not")
            || self.check_symbol("-")
            || self.check_symbol("#")
        {
            let op = match self.advance()? {
                Token::Keyword(k) => k,
                Token::Symbol(s) => s,
                _ => unreachable!(),
            };
            let expr = self.parse_sub_expr(8)?;
            Expr::UnaryOp {
                op,
                expr: Box::new(expr),
            }
        } else {
            self.parse_primary_expr()?
        };

        while let Some((prec, right_prec)) = self.binary_prec() {
            if prec < limit {
                break;
            }
            let op = match self.advance()? {
                Token::Keyword(k) => k,
                Token::Symbol(s) => s,
                _ => unreachable!(),
            };
            let right = self.parse_sub_expr(right_prec)?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn binary_prec(&self) -> Option<(u8, u8)> {
        match &self.current {
            Token::Keyword(k) if k == "or" => Some((1, 1)),
            Token::Keyword(k) if k == "and" => Some((2, 2)),
            Token::Symbol(s) => match s.as_str() {
                "==" | "~=" | "<" | "<=" | ">" | ">=" => Some((3, 3)),
                ".." => Some((4, 4)),
                "+" | "-" => Some((5, 5)),
                "*" | "/" | "%" => Some((6, 6)),
                "^" => Some((7, 7)),
                _ => None,
            },
            _ => None,
        }
    }

    fn parse_primary_expr(&mut self) -> Result<Expr, String> {
        let mut expr = match &self.current {
            Token::Keyword(k) if k == "nil" => {
                self.advance()?;
                Expr::Nil
            }
            Token::Keyword(k) if k == "true" => {
                self.advance()?;
                Expr::Bool(true)
            }
            Token::Keyword(k) if k == "false" => {
                self.advance()?;
                Expr::Bool(false)
            }
            Token::Keyword(k) if k == "function" => {
                self.advance()?;
                let (params, vararg, body) = self.parse_func_body()?;
                Expr::Function {
                    params,
                    vararg,
                    body,
                }
            }
            Token::Number(n) => {
                let num = *n;
                self.advance()?;
                Expr::Number(num)
            }
            Token::String(s) => {
                let str_val = s.clone();
                self.advance()?;
                Expr::String(str_val)
            }
            Token::Symbol(s) if s == "..." => {
                self.advance()?;
                Expr::Vararg
            }
            Token::Ident(s) => {
                let name = s.clone();
                self.advance()?;
                Expr::Var(name)
            }
            Token::Symbol(s) if s == "(" => {
                self.advance()?;
                let inner = self.parse_expr()?;
                self.consume_symbol(")")?;
                inner
            }
            Token::Symbol(s) if s == "{" => self.parse_table_constructor()?,
            other => return Err(format!("Unexpected token in expression: {:?}", other)),
        };

        loop {
            if self.check_symbol(".") {
                self.advance()?;
                let field = self.parse_ident()?;
                expr = Expr::Field {
                    target: Box::new(expr),
                    field,
                };
            } else if self.check_symbol("[") {
                self.advance()?;
                let key = self.parse_expr()?;
                self.consume_symbol("]")?;
                expr = Expr::Index {
                    target: Box::new(expr),
                    key: Box::new(key),
                };
            } else if self.check_symbol(":") {
                self.advance()?;
                let method = self.parse_ident()?;
                let args = self.parse_args()?;
                expr = Expr::MethodCall {
                    target: Box::new(expr),
                    method,
                    args,
                };
            } else if self.check_symbol("(") || matches!(&self.current, Token::String(_)) || self.check_symbol("{") {
                let args = self.parse_args()?;
                expr = Expr::Call {
                    func: Box::new(expr),
                    args,
                };
            } else {
                break;
            }
        }

        Ok(expr)
    }

    fn parse_args(&mut self) -> Result<Vec<Expr>, String> {
        if self.check_symbol("(") {
            self.advance()?;
            let mut args = Vec::new();
            if !self.check_symbol(")") {
                args = self.parse_expr_list()?;
            }
            self.consume_symbol(")")?;
            Ok(args)
        } else if matches!(&self.current, Token::String(_)) {
            let s = match self.advance()? {
                Token::String(str_val) => str_val,
                _ => unreachable!(),
            };
            Ok(vec![Expr::String(s)])
        } else if self.check_symbol("{") {
            let table = self.parse_table_constructor()?;
            Ok(vec![table])
        } else {
            Err(format!("Expected function arguments, got {:?}", self.current))
        }
    }

    fn parse_table_constructor(&mut self) -> Result<Expr, String> {
        self.consume_symbol("{")?;
        let mut fields = Vec::new();
        while !self.check_symbol("}") && self.current != Token::Eof {
            if self.check_symbol("[") {
                self.advance()?;
                let key = self.parse_expr()?;
                self.consume_symbol("]")?;
