use crate::lua::parser::{Expr, Stmt};
use crate::lua::value::{LuaFunc, LuaTable, LuaValue};
use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

#[derive(Clone, Debug, Default)]
pub struct Env {
    pub parent: Option<Rc<RefCell<Env>>>,
    pub vars: BTreeMap<String, LuaValue>,
}

impl Env {
    pub fn new() -> Self {
        Env {
            parent: None,
            vars: BTreeMap::new(),
        }
    }

    pub fn with_parent(parent: Rc<RefCell<Env>>) -> Self {
        Env {
            parent: Some(parent),
            vars: BTreeMap::new(),
        }
    }

    pub fn get(&self, name: &str) -> LuaValue {
        if let Some(v) = self.vars.get(name) {
            v.clone()
        } else if let Some(p) = &self.parent {
            p.borrow().get(name)
        } else {
            LuaValue::Nil
        }
    }

    pub fn set_local(&mut self, name: String, val: LuaValue) {
        self.vars.insert(name, val);
    }

    pub fn set_global_or_update(&mut self, name: &str, val: LuaValue) {
        if self.vars.contains_key(name) {
            self.vars.insert(name.to_string(), val);
        } else if let Some(p) = &self.parent {
            p.borrow_mut().set_global_or_update(name, val);
        } else {
            self.vars.insert(name.to_string(), val);
        }
    }
}

pub enum Flow {
    None,
    Return(Vec<LuaValue>),
    Break,
}

pub struct Evaluator {
    pub global_env: Rc<RefCell<Env>>,
}

impl Evaluator {
    pub fn new() -> Self {
        let global_env = Rc::new(RefCell::new(Env::new()));
        let mut eval = Evaluator { global_env };
        eval.init_stdlib();
        eval
    }

    fn init_stdlib(&mut self) {
        let env = self.global_env.clone();

        // _G
        let _g = LuaValue::Table(Rc::new(RefCell::new(LuaTable::new())));
        env.borrow_mut().set_local("_G".into(), _g.clone());

        // _VERSION
        env.borrow_mut()
            .set_local("_VERSION".into(), LuaValue::String("Lua 5.1".into()));

        // type
        let f_type = LuaValue::RustFunc(Rc::new(|args| {
            let val = args.first().cloned().unwrap_or(LuaValue::Nil);
            Ok(vec![LuaValue::String(val.type_name().into())])
        }));
        env.borrow_mut().set_local("type".into(), f_type);

        // tostring
        let f_tostring = LuaValue::RustFunc(Rc::new(|args| {
            let val = args.first().cloned().unwrap_or(LuaValue::Nil);
            Ok(vec![LuaValue::String(val.to_string_lossy())])
        }));
        env.borrow_mut().set_local("tostring".into(), f_tostring);

        // tonumber
        let f_tonumber = LuaValue::RustFunc(Rc::new(|args| {
            let val = args.first().cloned().unwrap_or(LuaValue::Nil);
            match val {
                LuaValue::Number(n) => Ok(vec![LuaValue::Number(n)]),
                LuaValue::String(s) => {
                    if let Ok(n) = s.trim().parse::<f64>() {
                        Ok(vec![LuaValue::Number(n)])
                    } else {
                        Ok(vec![LuaValue::Nil])
                    }
                }
                _ => Ok(vec![LuaValue::Nil]),
            }
        }));
        env.borrow_mut().set_local("tonumber".into(), f_tonumber);

        // print
        let f_print = LuaValue::RustFunc(Rc::new(|args| {
            let s: Vec<String> = args.iter().map(|a| a.to_string_lossy()).collect();
            println!("{}", s.join("\t"));
            Ok(vec![])
        }));
        env.borrow_mut().set_local("print".into(), f_print);

        // pairs
        let f_pairs = LuaValue::RustFunc(Rc::new(|args| {
            let tbl = match args.first() {
                Some(LuaValue::Table(t)) => t.clone(),
                _ => return Ok(vec![LuaValue::Nil]),
            };
            let keys: Vec<String> = tbl.borrow().map.keys().cloned().collect();
            let idx = Rc::new(RefCell::new(0));
            let next_fn = LuaValue::RustFunc(Rc::new(move |_| {
                let mut i = idx.borrow_mut();
                if *i < keys.len() {
                    let k = keys[*i].clone();
                    let v = tbl.borrow().map.get(&k).cloned().unwrap_or(LuaValue::Nil);
                    *i += 1;
                    Ok(vec![LuaValue::String(k), v])
                } else {
                    Ok(vec![LuaValue::Nil])
                }
            }));
            Ok(vec![next_fn])
        }));
        env.borrow_mut().set_local("pairs".into(), f_pairs);

        // ipairs
        let f_ipairs = LuaValue::RustFunc(Rc::new(|args| {
            let tbl = match args.first() {
                Some(LuaValue::Table(t)) => t.clone(),
                _ => return Ok(vec![LuaValue::Nil]),
            };
            let idx = Rc::new(RefCell::new(1));
            let arr_len = tbl.borrow().array.len();
            let next_fn = LuaValue::RustFunc(Rc::new(move |_| {
                let mut i = idx.borrow_mut();
                if *i <= arr_len {
                    let cur = *i;
                    let v = tbl.borrow().array[cur - 1].clone();
                    *i += 1;
                    Ok(vec![LuaValue::Number(cur as f64), v])
                } else {
                    Ok(vec![LuaValue::Nil])
                }
            }));
            Ok(vec![next_fn])
        }));
        env.borrow_mut().set_local("ipairs".into(), f_ipairs);

        // math
        let math_tbl = Rc::new(RefCell::new(LuaTable::new()));
        math_tbl.borrow_mut().set(
            LuaValue::String("sin".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let n = match a.first() {
                    Some(LuaValue::Number(num)) => *num,
                    _ => 0.0,
                };
                Ok(vec![LuaValue::Number(n.sin())])
            })),
        );
        math_tbl.borrow_mut().set(
            LuaValue::String("cos".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let n = match a.first() {
                    Some(LuaValue::Number(num)) => *num,
                    _ => 0.0,
                };
                Ok(vec![LuaValue::Number(n.cos())])
            })),
        );
        math_tbl.borrow_mut().set(
            LuaValue::String("floor".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let n = match a.first() {
                    Some(LuaValue::Number(num)) => *num,
                    _ => 0.0,
                };
                Ok(vec![LuaValue::Number(n.floor())])
            })),
        );
        math_tbl.borrow_mut().set(
            LuaValue::String("ceil".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let n = match a.first() {
                    Some(LuaValue::Number(num)) => *num,
                    _ => 0.0,
                };
                Ok(vec![LuaValue::Number(n.ceil())])
            })),
        );
        env.borrow_mut()
            .set_local("math".into(), LuaValue::Table(math_tbl));

        // string
        let string_tbl = Rc::new(RefCell::new(LuaTable::new()));
        string_tbl.borrow_mut().set(
            LuaValue::String("upper".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let s = a.first().map(|v| v.to_string_lossy()).unwrap_or_default();
                Ok(vec![LuaValue::String(s.to_uppercase())])
            })),
        );
        string_tbl.borrow_mut().set(
            LuaValue::String("lower".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let s = a.first().map(|v| v.to_string_lossy()).unwrap_or_default();
                Ok(vec![LuaValue::String(s.to_lowercase())])
            })),
        );
        env.borrow_mut()
            .set_local("string".into(), LuaValue::Table(string_tbl));

        // table
        let table_tbl = Rc::new(RefCell::new(LuaTable::new()));
        table_tbl.borrow_mut().set(
            LuaValue::String("concat".into()),
            LuaValue::RustFunc(Rc::new(|a| {
                let tbl = match a.first() {
                    Some(LuaValue::Table(t)) => t.clone(),
                    _ => return Ok(vec![LuaValue::String("".into())]),
                };
                let sep = a.get(1).map(|v| v.to_string_lossy()).unwrap_or_default();
                let strs: Vec<String> =
                    tbl.borrow().array.iter().map(|v| v.to_string_lossy()).collect();
                Ok(vec![LuaValue::String(strs.join(&sep))])
            })),
        );
        env.borrow_mut()
            .set_local("table".into(), LuaValue::Table(table_tbl));
    }

    pub fn eval_stmt(&mut self, env: Rc<RefCell<Env>>, stmt: &Stmt) -> Result<Flow, String> {
        match stmt {
            Stmt::Assign { targets, values } => {
                let mut vals = Vec::new();
                for v in values {
                    vals.push(self.eval_expr(env.clone(), v)?);
                }
                for (i, target) in targets.iter().enumerate() {
                    let val = vals.get(i).cloned().unwrap_or(LuaValue::Nil);
                    self.assign_target(env.clone(), target, val)?;
                }
            }
            Stmt::LocalAssign { names, values } => {
                let mut vals = Vec::new();
                for v in values {
                    vals.push(self.eval_expr(env.clone(), v)?);
                }
                for (i, name) in names.iter().enumerate() {
                    let val = vals.get(i).cloned().unwrap_or(LuaValue::Nil);
                    env.borrow_mut().set_local(name.clone(), val);
                }
            }
            Stmt::Call(expr) => {
                self.eval_expr(env, expr)?;
            }
            Stmt::If {
                cond_blocks,
                else_block,
            } => {
                for (cond, body) in cond_blocks {
                    if self.eval_expr(env.clone(), cond)?.is_truthy() {
                        let block_env = Rc::new(RefCell::new(Env::with_parent(env)));
                        return self.eval_chunk(block_env, body);
                    }
                }
                if let Some(eb) = else_block {
                    let block_env = Rc::new(RefCell::new(Env::with_parent(env)));
                    return self.eval_chunk(block_env, eb);
                }
            }
            Stmt::ForNum {
                name,
                start,
                stop,
                step,
                body,
            } => {
                let start_num = match self.eval_expr(env.clone(), start)? {
                    LuaValue::Number(n) => n,
                    _ => 0.0,
                };
                let stop_num = match self.eval_expr(env.clone(), stop)? {
                    LuaValue::Number(n) => n,
                    _ => 0.0,
                };
                let step_num = if let Some(s) = step {
                    match self.eval_expr(env.clone(), s)? {
                        LuaValue::Number(n) => n,
                        _ => 1.0,
                    }
                } else {
                    1.0
                };

                let mut cur = start_num;
                while (step_num > 0.0 && cur <= stop_num) || (step_num < 0.0 && cur >= stop_num) {
                    let loop_env = Rc::new(RefCell::new(Env::with_parent(env.clone())));
                    loop_env
                        .borrow_mut()
                        .set_local(name.clone(), LuaValue::Number(cur));
                    let flow = self.eval_chunk(loop_env, body)?;
                    match flow {
                        Flow::Return(_) => return Ok(flow),
                        Flow::Break => break,
                        Flow::None => {}
                    }
                    cur += step_num;
                }
            }
            Stmt::ForIn { names, exprs, body } => {
                if let Some(first_expr) = exprs.first() {
                    let iterator = self.eval_expr(env.clone(), first_expr)?;
                    loop {
                        let res = self.call_value(iterator.clone(), vec![])?;
                        let first_val = res.first().cloned().unwrap_or(LuaValue::Nil);
                        if matches!(first_val, LuaValue::Nil) {
                            break;
                        }
                        let loop_env = Rc::new(RefCell::new(Env::with_parent(env.clone())));
                        for (i, name) in names.iter().enumerate() {
                            let val = res.get(i).cloned().unwrap_or(LuaValue::Nil);
                            loop_env.borrow_mut().set_local(name.clone(), val);
                        }
                        let flow = self.eval_chunk(loop_env, body)?;
                        match flow {
                            Flow::Return(_) => return Ok(flow),
                            Flow::Break => break,
                            Flow::None => {}
                        }
                    }
                }
            }
            Stmt::While { cond, body } => {
                while self.eval_expr(env.clone(), cond)?.is_truthy() {
                    let loop_env = Rc::new(RefCell::new(Env::with_parent(env.clone())));
                    let flow = self.eval_chunk(loop_env, body)?;
                    match flow {
                        Flow::Return(_) => return Ok(flow),
                        Flow::Break => break,
                        Flow::None => {}
                    }
                }
            }
            Stmt::Repeat { body, cond } => {
                loop {
                    let loop_env = Rc::new(RefCell::new(Env::with_parent(env.clone())));
                    let flow = self.eval_chunk(loop_env, body)?;
                    match flow {
                        Flow::Return(_) => return Ok(flow),
                        Flow::Break => break,
                        Flow::None => {}
                    }
                    if self.eval_expr(env.clone(), cond)?.is_truthy() {
                        break;
                    }
                }
            }
            Stmt::Return(exprs) => {
                let mut vals = Vec::new();
                for e in exprs {
                    vals.push(self.eval_expr(env.clone(), e)?);
                }
                return Ok(Flow::Return(vals));
            }
            Stmt::Break => return Ok(Flow::Break),
        }
        Ok(Flow::None)
    }

    pub fn eval_chunk(&mut self, env: Rc<RefCell<Env>>, stmts: &[Stmt]) -> Result<Flow, String> {
        for s in stmts {
            let flow = self.eval_stmt(env.clone(), s)?;
            if !matches!(flow, Flow::None) {
                return Ok(flow);
            }
        }
        Ok(Flow::None)
    }

    fn assign_target(
        &mut self,
        env: Rc<RefCell<Env>>,
        target: &Expr,
        val: LuaValue,
    ) -> Result<(), String> {
        match target {
            Expr::Var(name) => {
                env.borrow_mut().set_global_or_update(name, val);
            }
            Expr::Field { target, field } => {
                let tbl_val = self.eval_expr(env, target)?;
                if let LuaValue::Table(t) = tbl_val {
                    t.borrow_mut()
                        .set(LuaValue::String(field.clone()), val);
                }
            }
            Expr::Index { target, key } => {
                let tbl_val = self.eval_expr(env.clone(), target)?;
                let k_val = self.eval_expr(env, key)?;
                if let LuaValue::Table(t) = tbl_val {
                    t.borrow_mut().set(k_val, val);
                }
            }
            _ => return Err("Invalid assignment target".into()),
        }
        Ok(())
    }

    pub fn eval_expr(&mut self, env: Rc<RefCell<Env>>, expr: &Expr) -> Result<LuaValue, String> {
        match expr {
            Expr::Nil => Ok(LuaValue::Nil),
            Expr::Bool(b) => Ok(LuaValue::Bool(*b)),
            Expr::Number(n) => Ok(LuaValue::Number(*n)),
            Expr::String(s) => Ok(LuaValue::String(s.clone())),
            Expr::Vararg => Ok(LuaValue::Nil),
            Expr::Var(name) => Ok(env.borrow().get(name)),
            Expr::Field { target, field } => {
                let target_val = self.eval_expr(env, target)?;
                if let LuaValue::Table(t) = target_val {
                    Ok(t.borrow().get(&LuaValue::String(field.clone())))
                } else {
                    Ok(LuaValue::Nil)
                }
            }
            Expr::Index { target, key } => {
                let target_val = self.eval_expr(env.clone(), target)?;
                let key_val = self.eval_expr(env, key)?;
                if let LuaValue::Table(t) = target_val {
                    Ok(t.borrow().get(&key_val))
                } else {
                    Ok(LuaValue::Nil)
                }
            }
            Expr::Call { func, args } => {
                let f_val = self.eval_expr(env.clone(), func)?;
                let mut evaluated_args = Vec::new();
                for a in args {
                    evaluated_args.push(self.eval_expr(env.clone(), a)?);
                }
                let res = self.call_value(f_val, evaluated_args)?;
                Ok(res.first().cloned().unwrap_or(LuaValue::Nil))
            }
            Expr::MethodCall {
                target,
                method,
                args,
            } => {
                let target_val = self.eval_expr(env.clone(), target)?;
                let f_val = if let LuaValue::Table(ref t) = target_val {
                    t.borrow().get(&LuaValue::String(method.clone()))
                } else {
                    LuaValue::Nil
                };
                let mut evaluated_args = vec![target_val];
                for a in args {
                    evaluated_args.push(self.eval_expr(env.clone(), a)?);
                }
                let res = self.call_value(f_val, evaluated_args)?;
                Ok(res.first().cloned().unwrap_or(LuaValue::Nil))
            }
            Expr::Table(fields) => {
                let tbl = Rc::new(RefCell::new(LuaTable::new()));
                let mut arr_idx = 1;
                for (k, v) in fields {
                    let v_val = self.eval_expr(env.clone(), v)?;
                    if let Some(k_expr) = k {
                        let k_val = self.eval_expr(env.clone(), k_expr)?;
                        tbl.borrow_mut().set(k_val, v_val);
                    } else {
                        tbl.borrow_mut().set(LuaValue::Number(arr_idx as f64), v_val);
                        arr_idx += 1;
                    }
                }
                Ok(LuaValue::Table(tbl))
            }
            Expr::Function {
                params,
                vararg,
                body,
            } => Ok(LuaValue::Function(Rc::new(LuaFunc {
                params: params.clone(),
                vararg: *vararg,
                body: body.clone(),
                env: env.clone(),
            }))),
            Expr::BinOp { op, left, right } => {
                let l = self.eval_expr(env.clone(), left)?;
                let r = self.eval_expr(env, right)?;
                match op.as_str() {
                    "+" => {
                        let ln = l.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        let rn = r.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        Ok(LuaValue::Number(ln + rn))
                    }
                    "-" => {
                        let ln = l.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        let rn = r.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        Ok(LuaValue::Number(ln - rn))
                    }
                    "*" => {
                        let ln = l.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        let rn = r.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        Ok(LuaValue::Number(ln * rn))
                    }
                    "/" => {
                        let ln = l.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        let rn = r.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        Ok(LuaValue::Number(ln / rn))
                    }
                    ".." => Ok(LuaValue::String(format!(
                        "{}{}",
                        l.to_string_lossy(),
                        r.to_string_lossy()
                    ))),
                    "==" => Ok(LuaValue::Bool(l == r)),
                    "~=" => Ok(LuaValue::Bool(l != r)),
                    "and" => {
                        if l.is_truthy() {
                            Ok(r)
                        } else {
                            Ok(l)
                        }
                    }
                    "or" => {
                        if l.is_truthy() {
                            Ok(l)
                        } else {
                            Ok(r)
                        }
                    }
                    _ => Ok(LuaValue::Nil),
                }
            }
            Expr::UnaryOp { op, expr } => {
                let val = self.eval_expr(env, expr)?;
                match op.as_str() {
                    "not" => Ok(LuaValue::Bool(!val.is_truthy())),
                    "-" => {
                        let num = val.to_string_lossy().parse::<f64>().unwrap_or(0.0);
                        Ok(LuaValue::Number(-num))
                    }
                    "#" => match val {
                        LuaValue::String(s) => Ok(LuaValue::Number(s.len() as f64)),
                        LuaValue::Table(t) => Ok(LuaValue::Number(t.borrow().array.len() as f64)),
                        _ => Ok(LuaValue::Number(0.0)),
                    },
                    _ => Ok(LuaValue::Nil),
                }
            }
        }
    }

    pub fn call_value(&mut self, f_val: LuaValue, args: Vec<LuaValue>) -> Result<Vec<LuaValue>, String> {
        match f_val {
            LuaValue::RustFunc(rf) => rf(args),
            LuaValue::Function(func) => {
                let fn_env = Rc::new(RefCell::new(Env::with_parent(func.env.clone())));
                for (i, p) in func.params.iter().enumerate() {
                    let val = args.get(i).cloned().unwrap_or(LuaValue::Nil);
                    fn_env.borrow_mut().set_local(p.clone(), val);
                }
                let flow = self.eval_chunk(fn_env, &func.body)?;
                match flow {
                    Flow::Return(vals) => Ok(vals),
                    _ => Ok(vec![]),
                }
            }
            _ => Ok(vec![]),
        }
    }

    pub fn eval_script(&mut self, script: &str) -> Result<Vec<LuaValue>, String> {
        let mut parser = crate::lua::parser::Parser::new(script)?;
        let stmts = parser.parse_chunk()?;
        let flow = self.eval_chunk(self.global_env.clone(), &stmts)?;
        match flow {
            Flow::Return(vals) => Ok(vals),
            _ => Ok(vec![]),
        }
    }
}
EOF"}

