pub mod eval;
pub mod lexer;
pub mod parser;
pub mod value;

use eval::Evaluator;
use std::cell::RefCell;
use std::rc::Rc;
use value::{LuaTable, LuaValue};

pub fn json_to_lua(val: &serde_json::Value) -> LuaValue {
    match val {
        serde_json::Value::Null => LuaValue::Nil,
        serde_json::Value::Bool(b) => LuaValue::Bool(*b),
        serde_json::Value::Number(n) => LuaValue::Number(n.as_f64().unwrap_or(0.0)),
        serde_json::Value::String(s) => LuaValue::String(s.clone()),
        serde_json::Value::Array(arr) => {
            let tbl = Rc::new(RefCell::new(LuaTable::new()));
            for (i, elem) in arr.iter().enumerate() {
                tbl.borrow_mut()
                    .set(LuaValue::Number((i + 1) as f64), json_to_lua(elem));
            }
            LuaValue::Table(tbl)
        }
        serde_json::Value::Object(map) => {
            let tbl = Rc::new(RefCell::new(LuaTable::new()));
            for (k, v) in map {
                tbl.borrow_mut()
                    .set(LuaValue::String(k.clone()), json_to_lua(v));
            }
            LuaValue::Table(tbl)
        }
    }
}

pub fn lua_to_json(val: &LuaValue) -> serde_json::Value {
    match val {
        LuaValue::Nil => serde_json::Value::Null,
        LuaValue::Bool(b) => serde_json::Value::Bool(*b),
        LuaValue::Number(n) => {
            if let Some(num) = serde_json::Number::from_f64(*n) {
                serde_json::Value::Number(num)
            } else {
                serde_json::Value::Null
            }
        }
        LuaValue::String(s) => serde_json::Value::String(s.clone()),
        LuaValue::Table(t) => {
            let tbl = t.borrow();
            if !tbl.array.is_empty() && tbl.map.is_empty() {
                let arr: Vec<serde_json::Value> = tbl.array.iter().map(lua_to_json).collect();
                serde_json::Value::Array(arr)
            } else {
                let mut map = serde_json::Map::new();
                for (k, v) in &tbl.map {
                    map.insert(k.clone(), lua_to_json(v));
                }
                serde_json::Value::Object(map)
            }
        }
        _ => serde_json::Value::Null,
    }
}

pub fn setup_xplr_env(eval: &mut Evaluator, default_config: &serde_json::Value) {
    let xplr_tbl = Rc::new(RefCell::new(LuaTable::new()));

    // config
    let config_val = json_to_lua(default_config);
    xplr_tbl
        .borrow_mut()
        .set(LuaValue::String("config".into()), config_val);

    // fn
    let fn_tbl = Rc::new(RefCell::new(LuaTable::new()));
    fn_tbl.borrow_mut().set(
        LuaValue::String("builtin".into()),
        LuaValue::Table(Rc::new(RefCell::new(LuaTable::new()))),
    );
    fn_tbl.borrow_mut().set(
        LuaValue::String("custom".into()),
        LuaValue::Table(Rc::new(RefCell::new(LuaTable::new()))),
    );
    xplr_tbl
        .borrow_mut()
        .set(LuaValue::String("fn".into()), LuaValue::Table(fn_tbl));

    // util
    let util_tbl = Rc::new(RefCell::new(LuaTable::new()));

    // util.version
    util_tbl.borrow_mut().set(
        LuaValue::String("version".into()),
        LuaValue::RustFunc(Rc::new(|_| {
            let tbl = Rc::new(RefCell::new(LuaTable::new()));
            tbl.borrow_mut().set(
                LuaValue::String("major".into()),
                LuaValue::Number(1.0),
            );
            tbl.borrow_mut().set(
                LuaValue::String("minor".into()),
                LuaValue::Number(1.0),
            );
            tbl.borrow_mut().set(
                LuaValue::String("patch".into()),
                LuaValue::Number(0.0),
            );
            Ok(vec![LuaValue::Table(tbl)])
        })),
    );

    // util.to_json
    util_tbl.borrow_mut().set(
        LuaValue::String("to_json".into()),
        LuaValue::RustFunc(Rc::new(|args| {
            let val = args.first().cloned().unwrap_or(LuaValue::Nil);
            let json_val = lua_to_json(&val);
            let s = serde_json::to_string(&json_val).unwrap_or_default();
            Ok(vec![LuaValue::String(s)])
        })),
    );

    // util.from_json
    util_tbl.borrow_mut().set(
        LuaValue::String("from_json".into()),
        LuaValue::RustFunc(Rc::new(|args| {
            let s = args.first().map(|v| v.to_string_lossy()).unwrap_or_default();
            if let Ok(json_val) = serde_json::from_str::<serde_json::Value>(&s) {
                Ok(vec![json_to_lua(&json_val)])
            } else {
                Ok(vec![LuaValue::Nil])
            }
        })),
    );

    // util.to_yaml
    util_tbl.borrow_mut().set(
        LuaValue::String("to_yaml".into()),
        LuaValue::RustFunc(Rc::new(|args| {
            let val = args.first().cloned().unwrap_or(LuaValue::Nil);
            let json_val = lua_to_json(&val);
            let s = serde_yaml::to_string(&json_val).unwrap_or_default();
            Ok(vec![LuaValue::String(s)])
        })),
    );

    // util.from_yaml
    util_tbl.borrow_mut().set(
        LuaValue::String("from_yaml".into()),
        LuaValue::RustFunc(Rc::new(|args| {
            let s = args.first().map(|v| v.to_string_lossy()).unwrap_or_default();
            if let Ok(json_val) = serde_yaml::from_str::<serde_json::Value>(&s) {
                Ok(vec![json_to_lua(&json_val)])
            } else {
                Ok(vec![LuaValue::Nil])
            }
        })),
    );

    // util.debug
    util_tbl.borrow_mut().set(
        LuaValue::String("debug".into()),
        LuaValue::RustFunc(Rc::new(|args| {
