    Function(Rc<LuaFunc>),
    RustFunc(Rc<dyn Fn(Vec<LuaValue>) -> Result<Vec<LuaValue>, String>>),
}

impl PartialEq for LuaValue {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (LuaValue::Nil, LuaValue::Nil) => true,
            (LuaValue::Bool(a), LuaValue::Bool(b)) => a == b,
            (LuaValue::Number(a), LuaValue::Number(b)) => a == b,
            (LuaValue::String(a), LuaValue::String(b)) => a == b,
            (LuaValue::Table(a), LuaValue::Table(b)) => Rc::ptr_eq(a, b),
            (LuaValue::Function(a), LuaValue::Function(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

impl fmt::Debug for LuaValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LuaValue::Nil => write!(f, "nil"),
            LuaValue::Bool(b) => write!(f, "{}", b),
            LuaValue::Number(n) => write!(f, "{}", n),
            LuaValue::String(s) => write!(f, "{:?}", s),
            LuaValue::Table(t) => write!(f, "table: {:p}", Rc::as_ptr(t)),
            LuaValue::Function(_) => write!(f, "function"),
            LuaValue::RustFunc(_) => write!(f, "rust_function"),
        }
    }
}

impl LuaValue {
    pub fn is_truthy(&self) -> bool {
        match self {
            LuaValue::Nil => false,
            LuaValue::Bool(b) => *b,
            _ => true,
        }
    }

    pub fn type_name(&self) -> &'static str {
        match self {
            LuaValue::Nil => "nil",
            LuaValue::Bool(_) => "boolean",
            LuaValue::Number(_) => "number",
            LuaValue::String(_) => "string",
            LuaValue::Table(_) => "table",
            LuaValue::Function(_) | LuaValue::RustFunc(_) => "function",
        }
    }

    pub fn to_string_lossy(&self) -> String {
        match self {
            LuaValue::Nil => "nil".into(),
            LuaValue::Bool(b) => b.to_string(),
            LuaValue::Number(n) => {
                let n_val = *n;
                if n_val.fract() == 0.0 && n_val.abs() < 1e15 {
                    format!("{}", n_val as i64)
                } else {
                    format!("{}", n_val)
                }
            }
            LuaValue::String(s) => s.clone(),
            LuaValue::Table(t) => format!("table: {:p}", Rc::as_ptr(t)),
            LuaValue::Function(_) | LuaValue::RustFunc(_) => "function".into(),
        }
    }
}

#[derive(Default, Debug, Clone)]
pub struct LuaTable {
    pub array: Vec<LuaValue>,
    pub map: BTreeMap<String, LuaValue>,
}

impl LuaTable {
    pub fn new() -> Self {
        LuaTable {
            array: Vec::new(),
            map: BTreeMap::new(),
        }
    }

    pub fn get(&self, key: &LuaValue) -> LuaValue {
        match key {
            LuaValue::Number(n_ref) => {
                let n = *n_ref;
                let idx = n as usize;
                if n > 0.0 && idx as f64 == n && idx <= self.array.len() {
                    self.array[idx - 1].clone()
                } else {
                    self.map
                        .get(&key.to_string_lossy())
                        .cloned()
                        .unwrap_or(LuaValue::Nil)
                }
            }
            LuaValue::String(s) => self.map.get(s).cloned().unwrap_or(LuaValue::Nil),
            _ => self
                .map
                .get(&key.to_string_lossy())
                .cloned()
                .unwrap_or(LuaValue::Nil),
        }
    }

    pub fn set(&mut self, key: LuaValue, val: LuaValue) {
        match key {
            LuaValue::Number(n) => {
                let idx = n as usize;
                if n > 0.0 && idx as f64 == n {
                    if idx <= self.array.len() {
                        self.array[idx - 1] = val;
                        return;
                    } else if idx == self.array.len() + 1 {
                        self.array.push(val);
                        return;
                    }
                }
                if matches!(val, LuaValue::Nil) {
                    self.map.remove(&n.to_string());
                } else {
                    self.map.insert(n.to_string(), val);
                }
            }
            LuaValue::String(s) => {
                if matches!(val, LuaValue::Nil) {
                    self.map.remove(&s);
                } else {
                    self.map.insert(s, val);
                }
            }
            _ => {
                let k = key.to_string_lossy();
                if matches!(val, LuaValue::Nil) {
                    self.map.remove(&k);
                } else {
                    self.map.insert(k, val);
                }
            }
        }
    }
}

