use serde::{Deserialize, Serialize};
use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
pub struct Permission {
    pub user_read: bool,
    pub user_write: bool,
    pub user_execute: bool,
    pub group_read: bool,
    pub group_write: bool,
    pub group_execute: bool,
    pub other_read: bool,
    pub other_write: bool,
    pub other_execute: bool,
}

impl Permission {
    pub fn from_mode(mode: u32) -> Self {
        Permission {
            user_read: (mode & 0o400) != 0,
            user_write: (mode & 0o200) != 0,
            user_execute: (mode & 0o100) != 0,
            group_read: (mode & 0o040) != 0,
            group_write: (mode & 0o020) != 0,
            group_execute: (mode & 0o010) != 0,
            other_read: (mode & 0o004) != 0,
            other_write: (mode & 0o002) != 0,
            other_execute: (mode & 0o001) != 0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
pub struct ResolvedNodeMetadata {
    pub absolute_path: String,
    pub size: u64,
    pub is_dir: bool,
    pub is_file: bool,
    pub is_symlink: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
pub struct Node {
    pub parent: String,
    pub relative_path: String,
    pub absolute_path: String,
    pub extension: String,
    pub is_symlink: bool,
    pub is_broken: bool,
    pub is_dir: bool,
    pub is_file: bool,
    pub is_readonly: bool,
    pub mime_essence: String,
    pub size: u64,
    pub human_size: String,
    pub permissions: Permission,
    pub created: Option<u128>,
    pub last_modified: Option<u128>,
    pub uid: u32,
    pub gid: u32,
    pub canonical: Option<ResolvedNodeMetadata>,
    pub symlink: Option<ResolvedNodeMetadata>,
}

pub fn human_readable_size(size: u64) -> String {
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.1} KB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.1} MB", size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1} GB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

pub fn create_node<P: AsRef<Path>>(path: P) -> Option<Node> {
    let path = path.as_ref();
    let abs_path = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let abs_str = abs_path.to_string_lossy().to_string();

    let parent_str = abs_path
        .parent()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|| "/".into());

    let relative_path = abs_path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| abs_str.clone());

    let extension = abs_path
        .extension()
        .map(|e| e.to_string_lossy().to_string())
        .unwrap_or_default();

    let symlink_meta = fs::symlink_metadata(path).ok()?;
    let is_symlink = symlink_meta.file_type().is_symlink();

    let meta = fs::metadata(path);
    let (is_dir, is_file, is_broken, size, mode, uid, gid, mtime, ctime) = if let Ok(m) = meta {
        (
            m.is_dir(),
            m.is_file(),
            false,
            m.len(),
            m.permissions().mode(),
            m.uid(),
            m.gid(),
            m.mtime() as u128 * 1_000_000_000,
            m.ctime() as u128 * 1_000_000_000,
        )
    } else {
        (
            false,
            false,
            is_symlink,
            symlink_meta.len(),
            symlink_meta.permissions().mode(),
            symlink_meta.uid(),
            symlink_meta.gid(),
            symlink_meta.mtime() as u128 * 1_000_000_000,
            symlink_meta.ctime() as u128 * 1_000_000_000,
        )
    };

    let is_readonly = (mode & 0o200) == 0;
    let permissions = Permission::from_mode(mode);
    let human_size = human_readable_size(size);

    let mime_essence = if is_dir {
        "inode/directory".into()
    } else if is_symlink {
        "inode/symlink".into()
    } else {
        "application/octet-stream".into()
    };

    Some(Node {
        parent: parent_str,
        relative_path,
        absolute_path: abs_str,
        extension,
        is_symlink,
        is_broken,
        is_dir,
        is_file,
        is_readonly,
        mime_essence,
        size,
        human_size,
        permissions,
        created: Some(ctime),
        last_modified: Some(mtime),
        uid,
        gid,
        canonical: None,
        symlink: None,
    })
}

pub fn explore_dir<P: AsRef<Path>>(dir: P, show_hidden: bool) -> Vec<Node> {
    let mut nodes = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().to_string();
            if !show_hidden && name.starts_with('.') {
                continue;
            }
            if let Some(node) = create_node(&path) {
                nodes.push(node);
            }
        }
    }

    nodes.sort_by(|a, b| {
        if a.is_dir != b.is_dir {
            b.is_dir.cmp(&a.is_dir)
        } else {
            a.relative_path.to_lowercase().cmp(&b.relative_path.to_lowercase())
        }
    });

    nodes
}
EOF"}

