cat <<'EOF' > src/app.rs
use crate::cli::CliArgs;
use crate::config::default_config_json;
use crate::explorer::{explore_dir, create_node, Node};
use crate::lua::eval::Evaluator;
use crate::lua::setup_xplr_env;
use crate::message::{Message, parse_message};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
pub enum QuitAction {
    Quit,
    PrintPwd,
    PrintFocusPath,
    PrintSelection,
    PrintResult,
    PrintAppState,
    Terminate,
}

pub struct App {
    pub pwd: PathBuf,
    pub initial_pwd: PathBuf,
    pub vroot: Option<PathBuf>,
    pub focus_index: usize,
    pub directory_nodes: Vec<Node>,
    pub selection: Vec<Node>,
    pub mode: String,
    pub layout: String,
    pub input_buffer: String,
    pub logs: Vec<(String, String)>, // (level, message)
    pub history: Vec<PathBuf>,
    pub history_idx: usize,
    pub pid: u32,
    pub session_path: PathBuf,
    pub config: serde_json::Value,
    pub lua_eval: Evaluator,
    pub quit_action: Option<QuitAction>,
    pub cli_args: CliArgs,
}

impl App {
    pub fn new(cli_args: CliArgs) -> Result<Self, String> {
        let initial_pwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

        let pwd = if let Some(ref p) = cli_args.path {
            let path = PathBuf::from(p);
            if !path.exists() {
                return Err(format!("error: path doesn't exist: {}", p));
            }
            if path.is_dir() && !cli_args.force_focus {
                fs::canonicalize(&path).unwrap_or(path)
            } else {
                path.parent()
                    .map(|p| fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf()))
                    .unwrap_or(initial_pwd.clone())
            }
        } else {
            initial_pwd.clone()
        };

        let pid = std::process::id();
        let session_path = PathBuf::from(format!("/tmp/xplr/session/{}", pid));
        let _ = fs::create_dir_all(&session_path);

        let default_cfg = default_config_json();
        let mut lua_eval = Evaluator::new();
        setup_xplr_env(&mut lua_eval, &default_cfg);

        // Load config file if present
        if let Some(ref cfg_path) = cli_args.config {
            if let Ok(code) = fs::read_to_string(cfg_path) {
                let _ = lua_eval.eval_script(&code);
            }
        } else {
            let home_config = dirs::config_dir()
                .map(|p| p.join("xplr/init.lua"))
                .unwrap_or_default();
            if home_config.exists() {
                if let Ok(code) = fs::read_to_string(&home_config) {
                    let _ = lua_eval.eval_script(&code);
                }
            } else if Path::new("/etc/xplr/init.lua").exists() {
                if let Ok(code) = fs::read_to_string("/etc/xplr/init.lua") {
                    let _ = lua_eval.eval_script(&code);
                }
            }
        }

        // Extra config
        for extra in &cli_args.extra_configs {
            if let Ok(code) = fs::read_to_string(extra) {
                let _ = lua_eval.eval_script(&code);
            }
        }

        let show_hidden = lua_eval
            .global_env
            .borrow()
            .get("xplr")
            .to_string_lossy()
            .contains("show_hidden = true");

        let nodes = explore_dir(&pwd, show_hidden);

        let mut app = App {
            pwd: pwd.clone(),
            initial_pwd,
            vroot: cli_args.vroot.as_ref().map(PathBuf::from),
            focus_index: 0,
            directory_nodes: nodes,
            selection: Vec::new(),
            mode: "default".into(),
            layout: "default".into(),
            input_buffer: String::new(),
            logs: Vec::new(),
            history: vec![pwd],
            history_idx: 0,
            pid,
            session_path,
            config: default_cfg,
            lua_eval,
            quit_action: None,
            cli_args: cli_args.clone(),
        };

        // Handle positional selections or stdin selection
        for sel_path in &cli_args.selections {
            if !Path::new(sel_path).exists() {
                return Err(format!("error: path doesn't exist: {}", sel_path));
            }
            if let Some(node) = create_node(sel_path) {
                app.selection.push(node);
            }
        }

        // Handle --on-load messages
        for msg_str in &cli_args.on_load {
            if let Ok(msg) = parse_message(msg_str) {
                app.handle_message(msg);
            } else {
                // Try as raw LuaEval
                let _ = app.lua_eval.eval_script(msg_str);
            }
        }

        Ok(app)
    }

    pub fn focused_node(&self) -> Option<&Node> {
        self.directory_nodes.get(self.focus_index)
    }

    pub fn handle_message(&mut self, msg: Message) {
        match msg {
            Message::Quit => {
                self.quit_action = Some(QuitAction::Quit);
            }
            Message::PrintPwdAndQuit => {
                self.quit_action = Some(QuitAction::PrintPwd);
            }
            Message::PrintFocusPathAndQuit => {
                self.quit_action = Some(QuitAction::PrintFocusPath);
            }
            Message::PrintSelectionAndQuit => {
                self.quit_action = Some(QuitAction::PrintSelection);
            }
            Message::PrintResultAndQuit => {
                self.quit_action = Some(QuitAction::PrintResult);
            }
            Message::PrintAppStateAndQuit => {
                self.quit_action = Some(QuitAction::PrintAppState);
            }
            Message::Terminate => {
                self.quit_action = Some(QuitAction::Terminate);
            }
            Message::ExplorePwd => {
                self.directory_nodes = explore_dir(&self.pwd, false);
            }
            Message::FocusNext => {
                if !self.directory_nodes.is_empty() {
                    self.focus_index = (self.focus_index + 1) % self.directory_nodes.len();
                }
            }
            Message::FocusPrevious => {
                if !self.directory_nodes.is_empty() {
                    if self.focus_index == 0 {
                        self.focus_index = self.directory_nodes.len() - 1;
                    } else {
                        self.focus_index -= 1;
                    }
                }
            }
            Message::FocusFirst => {
                self.focus_index = 0;
            }
            Message::FocusLast => {
                if !self.directory_nodes.is_empty() {
                    self.focus_index = self.directory_nodes.len() - 1;
                }
            }
            Message::ChangeDirectory(target) => {
                let target_path = PathBuf::from(target);
                if target_path.is_dir() {
                    self.pwd = fs::canonicalize(&target_path).unwrap_or(target_path);
                    self.directory_nodes = explore_dir(&self.pwd, false);
                    self.focus_index = 0;
                }
            }
            Message::LogInfo(s) => {
                self.logs.push(("INFO".into(), s));
            }
            Message::LogSuccess(s) => {
                self.logs.push(("SUCCESS".into(), s));
            }
            Message::LogWarning(s) => {
                self.logs.push(("WARNING".into(), s));
            }
            Message::LogError(s) => {
                self.logs.push(("ERROR".into(), s));
            }
            Message::LuaEval(s) => {
                let _ = self.lua_eval.eval_script(&s);
            }
            Message::LuaEvalSilently(s) => {
                let _ = self.lua_eval.eval_script(&s);
            }
            Message::SwitchMode(m) => {
                self.mode = m;
            }
            Message::ToggleSelection => {
                if let Some(node) = self.focused_node().cloned() {
                    if let Some(pos) = self.selection.iter().position(|n| n.absolute_path == node.absolute_path) {
                        self.selection.remove(pos);
                    } else {
                        self.selection.push(node);
                    }
                }
            }
            _ => {}
        }
    }

    pub fn app_state_yaml(&self) -> String {
        let mut state_map = serde_json::Map::new();
        state_map.insert("bin".into(), serde_json::Value::String(env::current_exe().map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|_| "./executable".into())));
        state_map.insert("version".into(), serde_json::Value::String("1.1.0".into()));
        state_map.insert("config".into(), self.config.clone());
        state_map.insert("pwd".into(), serde_json::Value::String(self.pwd.to_string_lossy().to_string()));
        state_map.insert("initial_pwd".into(), serde_json::Value::String(self.initial_pwd.to_string_lossy().to_string()));
        state_map.insert("mode".into(), serde_json::Value::String(self.mode.clone()));
        state_map.insert("layout".into(), serde_json::Value::String(self.layout.clone()));
        state_map.insert("pid".into(), serde_json::Value::Number(self.pid.into()));
        state_map.insert("session_path".into(), serde_json::Value::String(self.session_path.to_string_lossy().to_string()));

        let sel_arr: Vec<serde_json::Value> = self.selection.iter().map(|n| serde_json::to_value(n).unwrap()).collect();
        state_map.insert("selection".into(), serde_json::Value::Array(sel_arr));

        serde_yaml::to_string(&state_map).unwrap_or_default()
    }
}
EOF

