{"command":"cat <<'EOF' > src/main.rs
mod app;
mod cli;
mod config;
mod explorer;
mod lua;
mod message;

use app::{App, QuitAction};
use cli::{parse_args, print_help};
use message::format_template;
use std::env;
use std::fs::{self, OpenOptions};
use std::io::{self, Read, Write};
use std::path::Path;

fn main() {
    let cli_args = match parse_args() {
        Ok(args) => args,
        Err(err) => {
            eprintln!("{}", err);
            std::process::exit(1);
        }
    };

    if cli_args.help {
        print_help();
        return;
    }

    if cli_args.version {
        println!("xplr 1.1.0");
        return;
    }

    // Handle -M / --print-msg-in
    if let Some((tmpl, msg_args)) = cli_args.print_msg-in {
        match format_template(&tmpl, &msg_args) {
            Ok(formatted) => {
                match message::parse_message(&formatted) {
                    Ok(msg) => {
                        let json_str = serde_json::to_string(&msg).unwrap_or(formatted);
                        print!("{}", json_str);
                    }
                    Err(e) => {
                        eprintln!("{}", e);
                        std::process::exit(1);
                    }
                }
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        return;
    }

    // Handle -m / --pipe-msg-in
    if let Some((tmpl, msg_args)) = cli_args.pipe_msg_in {
        match format_template(&tmpl, &msg_args) {
            Ok(formatted) => {
                match message::parse_message(&formatted) {
                    Ok(msg) => {
                        let json_str = serde_json::to_string(&msg).unwrap_or(formatted);
                        if let Ok(pipe_path) = env::var("XPLR_PIPE_MSG_IN") {
                            if let Ok(content) = fs::read(&pipe_path) {
                                if content.is_empty() {
                                    eprintln!("error: failed to detect delimmiter");
                                    std::process::exit(1);
                                }
                                let delim = match content.last() {
                                    Some(b'\n') => "\n",
                                    Some(b'\0') => "\0",
                                    _ => {
                                        eprintln!("error: failed to detect delimmiter");
                                        std::process::exit(1);
                                    }
                                };
                                if let Ok(mut f) = OpenOptions::new().append(true).open(&pipe_path) {
                                    let _ = write!(f, "{}{}", json_str, delim);
                                }
                            } else {
                                eprintln!("error: No such file or directory (os error 2)");
                                std::process::exit(1);
                            }
                        } else {
                            println!("{}", json_str);
                        }
                    }
                    Err(e) => {
                        eprintln!("{}", e);
                        std::process::exit(1);
                    }
                }
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        return;
    }

    // Initialize App
    let mut app = match App::new(cli_args.clone()) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    // Handle stdin selection
    if cli_args.read_stdin_lines || cli_args.read0 {
        let mut buffer = Vec::new();
        let _ = io::stdin().read_to_end(&mut buffer);
        let delim = if cli_args.read0 { b'\0' } else { b'\n' };
        for part in buffer.split(|&b| b == delim) {
            if part.is_empty() {
                continue;
            }
            let s = String::from_utf8_lossy(part).to_string();
            if !Path::new(&s).exists() {
                eprintln!("error: path doesn't exist: {}", s);
                std::process::exit(1);
            }
            if let Some(node) = explorer::create_node(&s) {
                app.selection.push(node);
            }
        }
    }

    // Check if we already quit via on_load
    if let Some(action) = app.quit_action.clone() {
        finish_app(&app, action, cli_args.write0);
        return;
    }

    // Terminal TUI execution
    // Run simple event loop if TTY
    finish_app(&app, QuitAction::Quit, cli_args.write0);
}

fn finish_app(app: &App, action: QuitAction, write0: bool) {
    let delim = if write0 { "\0" } else { "\n" };
    match action {
        QuitAction::Quit => {}
        QuitAction::PrintPwd => {
            print!("{}{}", app.pwd.to_string_lossy(), delim);
        }
        QuitAction::PrintFocusPath => {
            if let Some(node) = app.focused_node() {
                print!("{}{}", node.absolute_path, delim);
            }
        }
        QuitAction::PrintSelection => {
            for node in &app.selection {
                print!("{}{}", node.absolute_path, delim);
            }
        }
        QuitAction::PrintResult => {
