use serde::{Deserialize, Serialize};

pub fn format_template(tmpl: &str, args: &[String]) -> Result<String, String> {
    let mut result = String::new();
    let chars: Vec<char> = tmpl.chars().collect();
    let mut i = 0;
    let mut arg_idx = 0;

    while i < chars.len() {
        if chars[i] == '%' {
            i += 1;
            if i >= chars.len() {
                return Err("error: xplr -m: template ended with incomplete placeholder".into());
            }
            let c = chars[i];
            let col = i;
            match c {
                's' => {
                    if arg_idx >= args.len() {
                        return Err(format!(
                            "error: xplr -m: placeholder missing value at column {}",
                            col
                        ));
                    }
                    result.push_str(&args[arg_idx]);
                    arg_idx += 1;
                }
                'q' => {
                    if arg_idx >= args.len() {
                        return Err(format!(
                            "error: xplr -m: placeholder missing value at column {}",
                            col
                        ));
                    }
                    let json_str = serde_json::to_string(&args[arg_idx]).unwrap();
                    result.push_str(&json_str);
                    arg_idx += 1;
                }
                '%' => {
                    result.push('%');
                }
                other => {
                    return Err(format!(
                        "error: xplr -m: invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                        other, col
                    ));
                }
            }
        } else {
            result.push(chars[i]);
        }
        i += 1;
    }

    if arg_idx < args.len() {
        return Err(
            "error: xplr -m: too many positional values, not enough positional placeholders".into(),
        );
    }

    Ok(result)
}

pub fn parse_message_value(s: &str) -> Result<serde_json::Value, String> {
    serde_yaml::from_str::<serde_json::Value>(s)
        .map_err(|e| format!("error: xplr -m: yaml: {}", e))
}

