pub enum Message {
    Quit,
    PrintPwdAndQuit,
    PrintFocusPathAndQuit,
    PrintSelectionAndQuit,
    PrintResultAndQuit,
    PrintAppStateAndQuit,
    Terminate,
    ExplorePwd,
    FocusNext,
    FocusPrevious,
    FocusFirst,
    FocusLast,
    ChangeDirectory(String),
    LogInfo(String),
    LogSuccess(String),
    LogWarning(String),
    LogError(String),
    LuaEval(String),
    LuaEvalSilently(String),
    SwitchMode(String),
    ToggleSelection,
    Other(serde_json::Value),
}

