cat <<'EOF' > src/ui/mod.rs
use crate::app::App;
use crossterm::event::{self, Event, KeyCode, KeyModifiers};
use crossterm::execute;
use crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::widgets::{Block, Borders, List, ListItem, Paragraph, Row, Table};
use ratatui::Terminal;
use std::io;
use std::time::Duration;

pub fn run_tui(app: &mut App) -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    loop {
        terminal.draw(|f| draw_ui(f, app))?;

        if app.quit_action.is_some() {
            break;
        }

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') => {
                        app.handle_message(crate::message::Message::Quit);
                        break;
                    }
                    KeyCode::Char('j') | KeyCode::Down => {
                        app.handle_message(crate::message::Message::FocusNext);
                    }
                    KeyCode::Char('k') | KeyCode::Up => {
                        app.handle_message(crate::message::Message::FocusPrevious);
                    }
                    KeyCode::Char('g') => {
                        app.handle_message(crate::message::Message::FocusFirst);
                    }
                    KeyCode::Char('G') => {
                        app.handle_message(crate::message::Message::FocusLast);
                    }
                    KeyCode::Char(' ') | KeyCode::Char('v') => {
                        app.handle_message(crate::message::Message::ToggleSelection);
                    }
                    KeyCode::Enter => {
                        app.handle_message(crate::message::Message::PrintResultAndQuit);
                        break;
                    }
                    KeyCode::Char(':') => {
                        app.handle_message(crate::message::Message::SwitchMode("action".into()));
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn draw_ui(f: &mut ratatui::Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(60), Constraint::Percentage(40)].as_ref())
        .split(f.area());

    let left_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Percentage(70), Constraint::Percentage(30)].as_ref())
        .split(chunks[0]);

    let right_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
        .split(chunks[1]);

    // Table view
    let header_cells = ["", "index", "relative_path", "permissions", "size"]
        .iter()
        .map(|h| ratatui::widgets::Cell::from(*h).style(Style::default().fg(Color::Yellow)));
    let header = Row::new(header_cells).height(1);

    let rows = app.directory_nodes.iter().enumerate().map(|(idx, node)| {
        let is_focused = idx == app.focus_index;
        let is_selected = app.selection.iter().any(|s| s.absolute_path == node.absolute_path);

        let sel_sym = if is_selected { "*" } else { " " };
        let style = if is_focused {
            Style::default().fg(Color::Black).bg(Color::Blue)
        } else if node.is_dir {
            Style::default().fg(Color::Blue)
        } else if node.is_symlink {
            Style::default().fg(Color::Cyan)
        } else {
            Style::default()
        };

        let cells = vec![
            ratatui::widgets::Cell::from(sel_sym),
            ratatui::widgets::Cell::from(idx.to_string()),
            ratatui::widgets::Cell::from(node.relative_path.clone()),
            ratatui::widgets::Cell::from("rwxr-xr-x"),
            ratatui::widgets::Cell::from(node.human_size.clone()),
        ];
        Row::new(cells).style(style)
    });

    let pwd_title = format!(" {} ", app.pwd.to_string_lossy());
    let table = Table::new(
        rows,
        [
            Constraint::Length(1),
            Constraint::Length(5),
            Constraint::Percentage(50),
            Constraint::Length(10),
            Constraint::Length(10),
        ],
    )
    .header(header)
    .block(Block::default().borders(Borders::ALL).title(pwd_title));

    f.render_widget(table, left_chunks[0]);

    // Help Menu
    let help_items = vec![
        ListItem::new("q - quit"),
        ListItem::new("j/down - focus next"),
        ListItem::new("k/up - focus previous"),
        ListItem::new("space/v - toggle selection"),
        ListItem::new("enter - quit with result"),
        ListItem::new(": - action mode"),
    ];
    let help_list = List::new(help_items)
        .block(Block::default().borders(Borders::ALL).title(" Help [default] "));
    f.render_widget(help_list, left_chunks[1]);

    // Selection
    let sel_items: Vec<ListItem> = app
        .selection
        .iter()
        .map(|n| ListItem::new(n.relative_path.clone()))
        .collect();
    let sel_list = List::new(sel_items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Selection ({}) ", app.selection.len())),
    );
    f.render_widget(sel_list, right_chunks[0]);

    // Input & Logs
    let last_log = app
        .logs
        .last()
        .map(|(lvl, msg)| format!("[{}] {}", lvl, msg))
        .unwrap_or_else(|| "❯ ".into());
    let input = Paragraph::new(last_log)
        .block(Block::default().borders(Borders::ALL).title(" Input & Logs "));
    f.render_widget(input, right_chunks[1]);
}
EOF"}

