                                std::process::exit(1);
                            }
                        } else {
                            println!("{}", json_str);
                        }
                    }
                    Err(e) => {
                        eprintln!("{}", e);
                        std::process::exit(1);
                    }
                }
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        return;
    }

    // Initialize App
    let mut app = match App::new(cli_args.clone()) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    // Handle stdin selection
    if cli_args.read_stdin_lines || cli_args.read0 {
        let mut buffer = Vec::new();
        let _ = io::stdin().read_to_end(&mut buffer);
        let delim = if cli_args.read0 { b'\0' } else { b'\n' };
        for part in buffer.split(|&b| b == delim) {
            if part.is_empty() {
                continue;
            }
            let s = String::from_utf8_lossy(part).to_string();
            if !Path::new(&s).exists() {
                eprintln!("error: path doesn't exist: {}", s);
                std::process::exit(1);
            }
            if let Some(node) = explorer::create_node(&s) {
                app.selection.push(node);
            }
        }
    }

    // Check if we already quit via on_load
    if let Some(action) = app.quit_action.clone() {
        finish_app(&app, action, cli_args.write0);
        return;
    }

    // Interactive TUI
    if let Err(e) = ui::run_tui(&mut app) {
        eprintln!("error: {}", e);
        std::process::exit(1);
    }

    let action = app.quit_action.clone().unwrap_or(QuitAction::Quit);
    finish_app(&app, action, cli_args.write0);
}

fn finish_app(app: &App, action: QuitAction, write0: bool) {
    let delim = if write0 { "\0" } else { "\n" };
    match action {
        QuitAction::Quit => {}
        QuitAction::PrintPwd => {
            print!("{}{}", app.pwd.to_string_lossy(), delim);
        }
        QuitAction::PrintFocusPath => {
            if let Some(node) = app.focused_node() {
                print!("{}{}", node.absolute_path, delim);
            }
        }
        QuitAction::PrintSelection => {
            for node in &app.selection {
                print!("{}{}", node.absolute_path, delim);
            }
        }
        QuitAction::PrintResult => {
            if !app.selection.is_empty() {
                for node in &app.selection {
                    print!("{}{}", node.absolute_path, delim);
                }
            } else if let Some(node) = app.focused_node() {
                print!("{}{}", node.absolute_path, delim);
            }
        }
        QuitAction::PrintAppState => {
            print!("{}", app.app_state_yaml());
        }
        QuitAction::Terminate => {
            std::process::exit(1);
        }
    }
}
